export default {"G000078":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Sites and presentations · structure · <code>G000078</code></p><h3>Finite étale site</h3><p>Use jointly surjective covering families among the finite étale objects over X. Over a connected pointed scheme their fibre functor gives a Galois category, which determines the profinite étale fundamental group.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0BL6\">Stacks 0BL6 · finite étale morphisms</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/pione/#tag-0BL6\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/0BND\">Stacks 0BND · the étale fundamental group</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/pione/#tag-0BND\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000078\">Open shared record</a></p></article>"};
